insert into public.questions (
  index, content, answer, category, lang, on_site, display, created_at, updated_at
)
values
  (1, 'Will a website actually help me get more clients?', 'Yes - a well-designed website works as your online storefront and a 24/7 salesperson. We focus not only on great design, but also on building trust and encouraging visitors to contact you. Our goal is simple: your website should generate real results, not just look good.', 'home', 'en', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (2, 'How much does a professional website really cost?', 'The cost depends on your needs, but the good news is - you don’t need to spend a fortune to have a professional online presence. We offer flexible packages tailored to small businesses and individuals just getting started. Tell us what you need and we’ll provide a clear quote - with no hidden fees.', 'home', 'en', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (3, 'What are the monthly costs? Are there any hidden fees?', 'We believe in full transparency. You’ll always know exactly what you’re paying for. No surprises, no hidden charges. Choose a plan that fits your budget, and we’ll explain everything clearly before we begin.', 'home', 'en', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (4, 'How quickly can my website go live?', 'For a simple website, you could be online within just a few days. We work efficiently and keep you updated at every stage. The faster we receive your materials, the faster your website can start working for your business.', 'home', 'en', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (5, 'I’m not tech-savvy - will I be able to manage it?', 'Absolutely. You don’t need any coding or technical knowledge. We explain everything in simple terms and guide you through the process. If you prefer, we can also handle everything for you so you don’t have to worry about a thing.', 'home', 'en', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (6, 'What if I want to make changes in the future?', 'Your website can grow along with your business. You can add new services, pages, or features at any time. We remain flexible and continue supporting you even after your site goes live.', 'home', 'en', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (7, 'Why should I choose you?', 'Because we focus on results. We build websites that create trust, attract clients, and help you sell. We care about design, performance, and security - but most importantly, we treat your business like it’s our own.', 'home', 'en', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (8, 'Why was Nucleify created?', 'Nucleify was designed to simplify page building and data management for both beginners and professionals.', 'about', 'en', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (9, 'What problems does it solve?', 'It streamlines data migration, integration, and analysis while providing a flexible PageBuilder for creating dynamic web pages.', 'about', 'en', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (10, 'Who can benefit from using Nucleify?', 'Nucleify is versatile and ideal for industries like finance, education, logistics, healthcare, and digital services.', 'about', 'en', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (11, 'Can I contribute to Nucleify?', 'Yes! Developers, designers, and testers are welcome to contribute through GitHub, bug reports, or feature suggestions.', 'about', 'en', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (12, 'What license does it use?', 'Nucleify is open-source under the BSD-3-Clause license, allowing free commercial and personal use.', 'about', 'en', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (13, 'Is it available in multiple languages?', 'Yes, Nucleify plans to support multiple languages, making it accessible to users worldwide.', 'about', 'en', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (14, 'How long does it take to build a website?', 'Depending on the plan, delivery times range from 5 days for a simple one-page website to 2 weeks for a full MVP. We work efficiently without compromising quality.', 'offer', 'en', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (15, 'Can I request changes after the website is delivered?', 'Yes! All our plans include revision periods ranging from 7 to 30 days, ensuring you get exactly what you envisioned.', 'offer', 'en', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (16, 'What payment options are available?', 'We accept all major credit cards through Stripe. You can choose between monthly payments or a one-time payment with a 20% discount.', 'offer', 'en', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (17, 'Is there a money-back guarantee?', 'Yes, we offer a 30-day money-back guarantee. If you''re not satisfied with our work, we''ll refund your payment - no questions asked.', 'offer', 'en', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (18, 'Can I request a custom plan?', 'Yes! If none of our standard plans fit your needs, we can create a custom plan tailored to your project. Just reach out to us via the contact form and we''ll put together a personalized offer.', 'offer', 'en', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (19, 'Can I upgrade or change my plan later?', 'Absolutely! You can upgrade your plan at any time. We''ll apply the difference in pricing and seamlessly transition your project to the new tier.', 'offer', 'en', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (20, 'What''s included in the monthly subscription?', 'Monthly plans include the full website development, hosting setup, and ongoing support. Minimum commitment is 6 months, after which you can cancel anytime.', 'offer', 'en', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (21, 'Will I fully own the website once it''s completed?', 'Yes, you''ll have full ownership of your website, including all source code, assets, and content. If you choose a monthly plan, ownership is transferred after the 6-month minimum commitment is completed. Once transferred, it''s yours to keep forever.', 'offer', 'en', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (22, 'Do you provide SEO and marketing support?', 'All our plans include SEO basics. Higher-tier plans come with Google Analytics integration and advanced SEO optimization to help you rank better.', 'offer', 'en', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (23, 'How does Nucleify handle data storage?', 'Nucleify offers flexible data storage for modular web apps, supporting databases, cloud storage, or hybrid setups, allowing you to store and manage data according to your project needs.', 'services', 'en', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (24, 'Can it help migrate data between systems?', 'Yes, Nucleify provides tools for smooth data migration between databases or legacy systems, minimizing disruption while ensuring your modular web apps stay fully functional.', 'services', 'en', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (25, 'How does Nucleify integrate with other software?', 'Nucleify includes APIs, plugins, and pre-built connectors to integrate seamlessly with external services and popular software systems, extending the functionality of your web applications.', 'services', 'en', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (26, 'What data analysis tools are available in Nucleify?', 'Nucleify offers built-in tools to filter, analyze, and visualize data, enabling actionable insights, report generation, and trend tracking for your web apps.', 'services', 'en', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (27, 'Can I create dynamic web pages with Nucleify?', 'Absolutely! Nucleify''s Page Builder lets you design and customize content-rich, dynamic pages easily, without advanced coding, for modular and responsive web applications.', 'services', 'en', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (28, 'Czy strona internetowa faktycznie pomoże mi zdobyć klientów?', 'Tak - dobrze zaprojektowana strona to Twoja wizytówka i sprzedawca 24/7. Dbamy nie tylko o wygląd, ale też o to, żeby strona budziła zaufanie i zachęcała do kontaktu. Naszym celem jest to, żeby Twoja strona realnie zarabiała, a nie tylko “ładnie wyglądała”.', 'home', 'pl', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (29, 'Ile naprawdę kosztuje profesjonalna strona internetowa?', 'Cena zależy od zakresu, ale dobra wiadomość jest taka: nie musisz wydawać fortuny, żeby mieć profesjonalną stronę. Mamy elastyczne pakiety dopasowane do małych firm i osób zaczynających. Powiedz nam, czego potrzebujesz, a przygotujemy konkretną wycenę - bez ukrytych kosztów.', 'home', 'pl', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (30, 'Ile zapłacę miesięcznie? Czy są jakieś ukryte opłaty?', 'Stawiamy na pełną przejrzystość. Otrzymujesz jasną informację, ile płacisz i za co. Żadnych niespodzianek ani ukrytych kosztów. Możesz wybrać plan dopasowany do budżetu, a my wszystko dokładnie wyjaśnimy przed startem.', 'home', 'pl', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (31, 'Jak szybko moja strona może zacząć działać?', 'W przypadku prostych stron możesz być online nawet w kilka dni. Działamy sprawnie i na każdym etapie informujemy Cię o postępach. Im szybciej dostaniemy materiały, tym szybciej Twoja strona zacznie pracować na Twój biznes.', 'home', 'pl', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (32, 'Nie znam się na technologii - czy dam sobie radę?', 'Oczywiście. Nie musisz znać się na kodowaniu ani technicznych sprawach. Wszystko tłumaczymy prostym językiem i pomagamy na każdym etapie. Możesz też zlecić nam pełną obsługę, jeśli nie chcesz zajmować się stroną samodzielnie.', 'home', 'pl', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (33, 'Co jeśli będę chciał coś zmienić w przyszłości?', 'Twoja strona może rozwijać się razem z Twoją firmą. W każdej chwili możesz dodać nowe usługi, podstrony czy funkcje. Jesteśmy elastyczni i wspieramy Cię także po uruchomieniu strony.', 'home', 'pl', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (34, 'Dlaczego warto wybrać właśnie Was?', 'Bo skupiamy się na efektach. Tworzymy strony, które budują zaufanie, przyciągają klientów i pomagają sprzedawać. Dbamy o estetykę, szybkość działania i bezpieczeństwo. A przede wszystkim - traktujemy Twój biznes tak, jakby był naszym własnym.', 'home', 'pl', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (35, 'Dlaczego powstał Nucleify?', 'Nucleify został stworzony, aby uprościć budowanie stron i zarządzanie danymi zarówno dla początkujących, jak i profesjonalistów.', 'about', 'pl', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (36, 'Jakie problemy rozwiązuje?', 'Usprawnia migrację, integrację i analizę danych, jednocześnie oferując elastyczny PageBuilder do tworzenia dynamicznych stron internetowych.', 'about', 'pl', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (37, 'Kto może skorzystać z Nucleify?', 'Nucleify jest wszechstronny i idealny dla branż takich jak finanse, edukacja, logistyka, opieka zdrowotna i usługi cyfrowe.', 'about', 'pl', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (38, 'Czy mogę wnieść swój wkład w Nucleify?', 'Tak! Programiści, projektanci i testerzy mogą współtworzyć projekt poprzez GitHub, zgłaszanie błędów lub propozycje nowych funkcji.', 'about', 'pl', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (39, 'Jakiej licencji używa?', 'Nucleify jest open-source na licencji BSD-3-Clause, umożliwiającej bezpłatne użytkowanie komercyjne i osobiste.', 'about', 'pl', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (40, 'Czy jest dostępny w wielu językach?', 'Tak, Nucleify planuje obsługę wielu języków, co czyni go dostępnym dla użytkowników na całym świecie.', 'about', 'pl', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (41, 'Jak długo trwa budowa strony internetowej?', 'W zależności od planu, czas realizacji wynosi od 5 dni dla prostej strony jednostronicowej do 2 tygodni dla pełnego MVP. Pracujemy efektywnie, nie rezygnując z jakości.', 'offer', 'pl', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (42, 'Czy mogę poprosić o zmiany po dostarczeniu strony?', 'Tak! Wszystkie nasze plany obejmują okresy rewizji od 7 do 30 dni, zapewniając, że otrzymasz dokładnie to, co sobie wyobraziłeś.', 'offer', 'pl', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (43, 'Jakie opcje płatności są dostępne?', 'Akceptujemy wszystkie główne karty kredytowe przez Stripe. Możesz wybrać między płatnościami miesięcznymi a jednorazową płatnością z 20% rabatem.', 'offer', 'pl', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (44, 'Czy jest gwarancja zwrotu pieniędzy?', 'Tak, oferujemy 30-dniową gwarancję zwrotu pieniędzy. Jeśli nie będziesz zadowolony z naszej pracy, zwrócimy Ci płatność — bez zbędnych pytań.', 'offer', 'pl', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (45, 'Czy mogę zamówić indywidualny plan?', 'Tak! Jeśli żaden z naszych standardowych planów nie odpowiada Twoim potrzebom, możemy stworzyć plan dopasowany do Twojego projektu. Skontaktuj się z nami przez formularz kontaktowy, a przygotujemy spersonalizowaną ofertę.', 'offer', 'pl', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (46, 'Czy mogę zmienić lub podwyższyć plan później?', 'Oczywiście! Możesz podwyższyć swój plan w dowolnym momencie. Naliczymy różnicę w cenie i płynnie przeniesiemy Twój projekt na wyższy poziom.', 'offer', 'pl', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (47, 'Co obejmuje miesięczna subskrypcja?', 'Plany miesięczne obejmują pełne tworzenie strony, konfigurację hostingu i bieżące wsparcie. Minimalny okres to 6 miesięcy, po którym możesz zrezygnować w dowolnym momencie.', 'offer', 'pl', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (48, 'Czy będę w pełni właścicielem strony po jej ukończeniu?', 'Tak, będziesz mieć pełną własność swojej strony, w tym cały kod źródłowy, zasoby i treści. W przypadku planu miesięcznego, własność jest przenoszona po zakończeniu 6-miesięcznego minimalnego okresu. Po przeniesieniu jest Twoja na zawsze.', 'offer', 'pl', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (49, 'Czy zapewniacie wsparcie SEO i marketingowe?', 'Wszystkie nasze plany zawierają podstawy SEO. Wyższe plany obejmują integrację z Google Analytics i zaawansowaną optymalizację SEO, aby pomóc Ci osiągnąć lepsze pozycje.', 'offer', 'pl', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (50, 'Jak Nucleify obsługuje przechowywanie danych?', 'Nucleify oferuje elastyczne przechowywanie danych dla modułowych aplikacji webowych, wspierając bazy danych, chmurę lub konfiguracje hybrydowe, pozwalając przechowywać i zarządzać danymi zgodnie z potrzebami projektu.', 'services', 'pl', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (51, 'Czy pomaga w migracji danych między systemami?', 'Tak, Nucleify zapewnia narzędzia do płynnej migracji danych między bazami danych lub starszymi systemami, minimalizując zakłócenia i utrzymując pełną funkcjonalność aplikacji.', 'services', 'pl', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (52, 'Jak Nucleify integruje się z innym oprogramowaniem?', 'Nucleify zawiera API, wtyczki i gotowe konektory do bezproblemowej integracji z zewnętrznymi usługami i popularnymi systemami, rozszerzając funkcjonalność Twoich aplikacji webowych.', 'services', 'pl', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (53, 'Jakie narzędzia do analizy danych są dostępne?', 'Nucleify oferuje wbudowane narzędzia do filtrowania, analizy i wizualizacji danych, umożliwiając generowanie raportów, śledzenie trendów i wyciąganie wniosków.', 'services', 'pl', true, true, date_trunc('second', now()), date_trunc('second', now())),
  (54, 'Czy mogę tworzyć dynamiczne strony w Nucleify?', 'Oczywiście! Page Builder Nucleify pozwala projektować i dostosowywać bogate w treść, dynamiczne strony bez zaawansowanego kodowania, dla modułowych i responsywnych aplikacji webowych.', 'services', 'pl', true, true, date_trunc('second', now()), date_trunc('second', now()))
on conflict do nothing;

insert into public.technologies (
  label, description, href, src, category, display, created_at, updated_at
)
values
  ('PHP', 'Popular server-side programming language, often used for creating dynamic websites and web applications.', 'https://www.php.net/', 'php.svg', 'general', true, date_trunc('second', now()), date_trunc('second', now())),
  ('Laravel', 'A PHP open-source framework designed for simple web application development with elegant and readable code.', 'https://laravel.com/', 'laravel.svg', 'general', true, date_trunc('second', now()), date_trunc('second', now())),
  ('TypeScript', 'A superset of JavaScript that adds static typing, which helps detect errors and improves code readability', 'https://www.typescriptlang.org/', 'typescript.svg', 'general', true, date_trunc('second', now()), date_trunc('second', now())),
  ('Nuxt', 'It provides a number of features that make it easy to build fast, SEO-friendly, and scalable web applications.', 'https://nuxt.com/', 'nuxt.svg', 'general', true, date_trunc('second', now()), date_trunc('second', now())),
  ('Vue', 'A progressive JavaScript framework for building user interfaces, known for its simplicity and performance.', 'https://vuejs.org/', 'vue.svg', 'general', true, date_trunc('second', now()), date_trunc('second', now())),
  ('PrimeVue', 'A UI component library for the Vue framework, offering a rich selection of ready-made user interface elements', 'https://primevue.org/', 'primevue.svg', 'general', true, date_trunc('second', now()), date_trunc('second', now())),
  ('GSAP', 'A JavaScript library for creating high-performance animations, easing, and transitions.', 'https://greensock.com/gsap/', 'gsap.svg', 'general', true, date_trunc('second', now()), date_trunc('second', now())),
  ('Chart.js', 'Simple yet flexible JavaScript charting library for the modern web', 'https://www.chartjs.org/', 'chart-js.svg', 'general', true, date_trunc('second', now()), date_trunc('second', now())),
  ('HTML5', 'The latest version of the HTML markup language. It enables the creation of responsive and semantic websites with multimedia support, without the need for additional plugins.', 'https://html.spec.whatwg.org/multipage/', 'html5.svg', 'general', true, date_trunc('second', now()), date_trunc('second', now())),
  ('SCSS (Sass)', 'A CSS preprocessor that extends its capabilities by adding variables, nesting rules, and other advanced features.', 'https://sass-lang.com/', 'scss.svg', 'general', true, date_trunc('second', now()), date_trunc('second', now())),
  ('MySQL', 'A relational database, popular in web applications. It enables the storage and management of large sets of data', 'https://www.mysql.com/', 'mysql.svg', 'general', true, date_trunc('second', now()), date_trunc('second', now())),
  ('Docker', 'A platform for containerizing applications, enabling the execution of apps in isolated environments. It simplifies the creation, deployment, and management of applications.', 'https://www.docker.com/', 'docker.svg', 'general', true, date_trunc('second', now()), date_trunc('second', now())),
  ('Heroku', 'A cloud-based PaaS (Platform-as-a-Service) platform, allowing easy deployment, scaling, and management of web applications', 'https://www.heroku.com/', 'heroku.svg', 'general', true, date_trunc('second', now()), date_trunc('second', now())),
  ('Vitest', 'A lightweight and fast testing framework for applications written in TypeScript and JavaScript, designed to work as a companion to Vite.', 'https://vitest.dev/', 'vitest.svg', 'general', true, date_trunc('second', now()), date_trunc('second', now())),
  ('Pest', 'A simple and elegant unit testing framework for PHP, designed with readability and performance in mind.', 'https://pestphp.com/', 'pest.svg', 'general', true, date_trunc('second', now()), date_trunc('second', now())),
  ('Cypress', 'An end-to-end testing framework for web applications. It allows fast and easy writing of user interface tests in real browsers.', 'https://www.cypress.io/', 'cypress.svg', 'general', true, date_trunc('second', now()), date_trunc('second', now())),
  ('Sonarcloud', 'A cloud-based tool for code quality analysis. It helps identify bugs, security issues, and technical debt.', 'https://www.sonarsource.com/products/sonarcloud/', 'sonarcloud.svg', 'general', true, date_trunc('second', now()), date_trunc('second', now())),
  ('Biome', 'A fast, modern, and powerful linter and formatter for JavaScript, TypeScript, and CSS.', 'https://biomejs.dev/', 'biome.svg', 'general', true, date_trunc('second', now()), date_trunc('second', now())),
  ('Stylelint', 'A linter for CSS and SCSS, helping enforce styling standards and detect errors in code.', 'https://stylelint.io/', 'stylelint.svg', 'general', true, date_trunc('second', now()), date_trunc('second', now())),
  ('Husky', 'A tool for managing Git hooks, enabling the execution of scripts (e.g., linting) before committing changes to a repository.', 'https://typicode.github.io/husky/', 'husky.svg', 'general', true, date_trunc('second', now()), date_trunc('second', now()))
on conflict do nothing;
